?><!doctype html><html><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Property Moderation | LeadsIndia</title><script src="https://cdn.tailwindcss.com"></script></head><body class="bg-slate-950 text-slate-100 min-h-screen"><header class="sticky top-0 z-20 bg-slate-950/95 border-b border-white/10"><div class="max-w-7xl mx-auto px-4 py-4 flex justify-between items-center"><div><div class="font-black text-xl">LeadsIndia Property Admin</div><div class="text-xs text-slate-400">Moderation & Publishing</div></div><a href="/properties.html" class="text-sm text-emerald-400">View public marketplace →</a></div></header><main class="max-w-7xl mx-auto p-4 py-8"><div class="flex gap-2 overflow-x-auto pb-3 mb-5"><?php $tabs=[''=>'ALL','PENDING_VERIFICATION'=>'PENDING','UNDER_REVIEW'=>'REVIEW','NEED_CORRECTION'=>'CORRECTION','VERIFIED'=>'VERIFIED','LIVE'=>'LIVE','REJECTED'=>'REJECTED']; foreach($tabs as $k=>$label):?><a href="?status=<?=e($k)?>" class="whitespace-nowrap px-3 py-2 rounded-xl text-xs font-bold border <?=($filter===$k?'bg-emerald-600 border-emerald-500':'bg-slate-900 border-white/10')?>"><?=e($label)?></a><?php endforeach;?></div><?php if(!$records):?><div class="rounded-2xl border border-white/10 bg-slate-900 p-8 text-center text-slate-400">No property submissions found.</div><?php endif;?><div class="space-y-4"><?php foreach($records as $r):$p=$r['property']??[];$o=$r['owner']??[];$photos=$p['photos']??[];?><article class="bg-slate-900 border border-white/10 rounded-2xl p-5"><div class="flex flex-col lg:flex-row gap-5"><div class="lg:w-56 shrink-0"><?php if(!empty($photos[0])):?><img src="<?=e($photos[0])?>" alt="Property" class="w-full h-40 object-cover rounded-xl"><?php else:?><div class="w-full h-40 bg-slate-800 rounded-xl grid place-items-center text-slate-500">No photo</div><?php endif;?></div><div class="flex-1 min-w-0"><div class="flex flex-wrap gap-2 items-center"><span class="text-xs font-mono text-slate-400"><?=e($r['reference_id']??'')?></span><span class="text-[11px] font-bold rounded-full px-2 py-1 bg-slate-800 border border-white/10"><?=e($r['status']??'')?></span></div><h2 class="font-black text-xl mt-2"><?=e(($p['configuration']??'').' '.($p['type']??''))?></h2><p class="text-sm text-slate-400"><?=e(($p['project_name']??'').' · '.($p['locality']??'').', '.($p['city']??''))?></p><div class="grid sm:grid-cols-2 lg:grid-cols-4 gap-3 mt-4 text-sm"><div><span class="text-slate-500 text-xs block">Owner</span><?=e($o['name']??'')?></div><div><span class="text-slate-500 text-xs block">Mobile</span><?=e($o['mobile']??'')?></div><div><span class="text-slate-500 text-xs block">Price/Rent</span>₹<?=e($p['price']??'')?></div><div><span class="text-slate-500 text-xs block">Submitted</span><?=e($r['created_at']??'')?></div></div><details class="mt-4"><summary class="cursor-pointer text-sm text-emerald-400 font-bold">Full details</summary><div class="mt-3 text-sm text-slate-300 space-y-2"><p><b>Address:</b> <?=e($p['address']??'')?></p><p><b>Area:</b> <?=e($p['area']??'')?></p><p><b>Description:</b> <?=nl2br(e($p['description']??''))?></p><?php if(count($photos)>1):?><div class="flex gap-2 flex-wrap"><?php foreach($photos as $ph):?><a target="_blank" href="<?=e($ph)?>"><img src="<?=e($ph)?>" class="w-20 h-20 object-cover rounded-lg"></a><?php endforeach;?></div><?php endif;?></div></details><form method="post" action="/admin/property-action.php" class="mt-5 flex flex-col md:flex-row gap-2"><input type="hidden" name="csrf" value="<?=e(li_csrf())?>"><input type="hidden" name="reference_id" value="<?=e($r['reference_id']??'')?>"><input name="note" maxlength="500" placeholder="Internal note / correction reason" class="flex-1 bg-slate-950 border border-white/10 rounded-xl px-3 py-2 text-sm"><select name="status" class="bg-slate-950 border border-white/10 rounded-xl px-3 py-2 text-sm"><?php foreach(li_allowed_statuses() as $s):?><option value="<?=e($s)?>" <?=($s===($r['status']??'')?'selected':'')?>><?=e($s)?></option><?php endforeach;?></select><button class="bg-emerald-600 hover:bg-emerald-500 px-4 py-2 rounded-xl font-bold text-sm">Update Status</button></form></div></div></article><?php endforeach;?></div></main></body></html>